  spviz: ['0–1 yaş', '1–2 yaş', '3–4 yaş', '5 yaş', '6 yaş', '7 yaş', '8 yaş'],
  sporient: ['0–1 yaş', '0–2 yaş', '1–2 yaş', '2–3 yaş', '4 yaş', '5 yaş', '6 yaş', '7 yaş', '8 yaş', '8 yaş'],
  mlen: ['0–2 yaş', '1–3 yaş', '4 yaş', '4–5 yaş', '4–5 yaş', '6 yaş', '6 yaş', '7 yaş', '7–8 yaş', '8 yaş', '8 yaş', '8 yaş'],
  marea: ['0–3 yaş', '3–4 yaş', '4–5 yaş', '5 yaş', '5–6 yaş', '6–7 yaş', '8 yaş', '8 yaş'],
